E=html.escape
STYLE='''body{margin:0;background:#edf2f1;color:#173642;font:17px/1.7 system-ui,-apple-system,sans-serif}header{background:#123d46;color:#fff;padding:55px max(24px,calc((100vw - 1080px)/2))}header p{max-width:800px;color:#d9ebe9}main{max-width:1080px;margin:30px auto 70px;padding:0 24px}h1{font-size:42px;line-height:1.1;letter-spacing:-1px;max-width:900px}h2{font-size:28px;line-height:1.25;margin:36px 0 14px}h3{font-size:21px;margin:25px 0 8px}p{max-width:88ch;overflow-wrap:anywhere}a{color:#08666d;text-underline-offset:3px}header a{color:#c5eedf}.card{background:white;border:1px solid #cbd9d8;border-radius:14px;padding:25px;margin:22px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.grid .card{margin:0}.note{background:#fcf3d7;border-left:4px solid #b47a1c;padding:16px 20px;margin:22px 0}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:13px 15px;text-align:left;vertical-align:top;border-bottom:1px solid #dce5e3}th{background:#deebe7;color:#123d46}img{max-width:100%;height:auto;border-radius:8px}figure{margin:22px 0}figcaption,.small{font-size:14px;color:#596e73}code{font:14px ui-monospace,monospace;background:#edf3f2;padding:2px 5px}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px;background:#e7efed;border-radius:9px;font:14px/1.6 ui-monospace,monospace}.buttons{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.button,button{background:#136b6d;color:white;padding:10px 16px;border-radius:7px;border:0;text-decoration:none;font:inherit;cursor:pointer}input,textarea,select{font:inherit;padding:10px;width:100%;box-sizing:border-box;border:1px solid #a1b4b2;border-radius:6px;background:#fff;color:#173642}textarea{min-height:115px}label{font-weight:650;display:block;margin:15px 0 5px}.answer{min-height:110px;border:1px solid #b8c8c5;border-radius:8px;margin:12px 0;background:white}.tag{font-size:12px;text-transform:uppercase;letter-spacing:2px;color:#a8dcca}.step{padding:15px 0;border-bottom:1px solid #d4dfdd}li{margin:8px 0}summary{cursor:pointer;font-weight:700}.sr{position:absolute;left:-10000px}@media(max-width:750px){.grid{grid-template-columns:1fr}h1{font-size:34px}header{padding:35px 24px}main{padding:0 16px}td,th{padding:10px}.card{padding:18px}}@media print{body{background:white;font-size:11pt}header{padding:0;background:white;color:#173642}header p{color:#173642}main{margin:0;padding:0}.buttons,button,.no-print{display:none}.card{break-inside:avoid;padding:12px}.table{overflow:visible}h2{break-after:avoid;font-size:20pt}table{font-size:10pt}.answer{min-height:100px}a{color:inherit}.tag{color:#173642}}
'''
def doc(name,title,subtitle,body):
    (OUT/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{STYLE}</style></head><body><header><div class="tag">Evidence Map · Teaching Studio · 2026–27</div><h1>{title}</h1><p>{subtitle}</p></header><main>{body}</main></body></html>')
def table(headers,rows):return '<div class="table"><table><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'
research=''.join(f'<li><a href="{E(s["url"])}">{E(s["title"])}</a> — {E(s["use"])}</li>' for s in D['research'])
changes=table(['Decision','Working rule','Why'],[
['Dated studio plan','Apply Citrus to its ten matching base lesson IDs; retain the previous files.','The revision supplies concrete next-five-class builds without guessing a crosswalk.'],
['Sneaker release','Keep as an alternative seven-class campaign.','It uses different IDs and needs a deliberate calendar substitution, not another seven classes added to the week.'],
['Course System v2','Use the 34-sprint architecture and opening tickets as reference.','Its dates and IDs differ from the dated plan. Thirty opening tickets do not constitute a fully fabricated year.'],
['IB year plan','Preserve the full-year workbook and dated 160-day sequence.','May reserve days depend on the coordinator’s actual exam timetable. No retrospective completion is inferred.'],
['MM12 Sound','Use the published five-outcome framework in the consolidated register; flag the old app’s seven-item transcription.','Position-based IDs after Sound have shifted. Existing judgments cannot be safely relabelled by ordinal number.'],
['Assessment percentages','Remove the automatic local-level and IB-grade-to-percent conversions.','The supplied rules do not authorise those conversions. Keep school reporting and IB predictions separate.'],
['Source books','Retain the books in their original local locations.','The release contains original diagnostic artwork and planning references, not republished book chapters or exercise assets.'],
['Duplicate files','Keep one accessible copy of each original workbook and preserve a complete source manifest.','Forty entries are byte-identical. Different project versions are alternatives, not duplicates.']])
guide=f'''<div class="buttons"><a class="button" href="../../index.html">Open Evidence Map</a><a class="button" href="Evidence_Map_and_Skills.xlsx" download>Download working Excel</a><a class="button" href="Photoshop_Diagnostic.html">Photoshop task</a><a class="button" href="Digital_Society_Diagnostic.html">Digital Society task</a><a class="button" href="Student_Skill_Passport.html" download>Student skill passport</a></div>
<div class="card"><h2>Use the number to choose the next teaching move</h2><p>Give each learner a dated, task-specific readiness profile, then make it easy to improve. A learner can need support with Photoshop masks and independently evaluate a Digital Society source. Keep both truths visible. Use mixed teams to practise, and individual evidence to decide what the learner can now do.</p><p>The proposal is a local classroom diagnostic informed by Kagan’s cooperative-learning principles. It is not a standardised Kagan test, a measure of intelligence, a permanent rank, or a validated predictor of course achievement.</p></div>
<p><a href="Digital_Society_Teacher_Key.html">Digital Society teacher reasoning key</a> · <a href="Fabrication_Prompts.md" download>Reusable fabrication prompts</a></p><h2>What Kagan contributes</h2><p>Kagan’s PIES framework asks teachers to structure shared benefit, individual accountability, balanced participation and simultaneous interaction. For this studio, that means every learner has a useful contribution, everyone makes or explains something individually, turns are distributed deliberately, and several pairs work at once. <a href="https://www.kaganonline.com/free_articles/dr_spencer_kagan/345/The-P-and-I-of-PIES-Powerful-Principles-for-Success">Kagan’s explanation of PIES</a>.</p><p>The provider recommends mixed base teams and frequent pair work within teams of four. Its articles offer rationale, practitioner reports and cited research of differing strength. They support designing a structured classroom pilot; they do not validate the Photoshop rubric or prove that a particular seating algorithm will improve marks. <a href="https://www.kaganonline.com/free_articles/dr_spencer_kagan/396/10-Reasons-to-Use-Heterogeneous-Teams">Heterogeneous teams</a>; <a href="https://www.kaganonline.com/free_articles/dr_spencer_kagan/532/Pairs_vs._Teams">Pairs and teams</a>.</p>
<h3>Three different uses of numbers</h3>{table(['Number','Meaning here','Use'],[['Task score 4–16','Sum of four observed criterion ratings, each 1–4.','A compact description of this attempt. Keep the four ratings visible.'],['Readiness band 1–4','A teacher-reviewed local support band for this task family.','Plan a useful next task and provisional group balance.'],['Seat 1–4','A place/turn identifier within a four-person team.','Choose who starts, operates, checks or explains. It says nothing about achievement.']])}
<p>Kagan TeamTools distinguishes entered scores from the relative achievement groups it creates. Its manual uses different numbering directions for entered band scores and generated quartile labels. It also removes teacher-only score information from the accepted student layout. Do not copy those labels into a growth scale. This app consistently uses higher readiness numbers for stronger demonstrated independence and neutral seat numbers. <a href="https://www.kaganonline.com/catalog/software_documentation/Manual-TeamTools.pdf">TeamTools manual, pp. 11–14 and 20</a>.</p>
<h2>The proposed readiness scale</h2>{table(['Band','Evidence','Teaching response'],[['1 · Beginning','A meaningful attempt is present but essential control or reasoning is not yet demonstrated.','Provide a short model, a small successful action and an early checkpoint.'],['2 · Developing','Parts work; the learner needs a specific hint or cannot yet explain the result reliably.','Use constrained practice, a coach who asks questions and one independent retry.'],['3 · Independent','The learner carries out and explains the taught task without instructional hints during the scored attempt.','Give a changed application and require a concise rationale.'],['4 · Transfer','The learner handles a new but related condition and explains a relevant trade-off.','Offer a more demanding decision, different audience or unfamiliar fault. Do not turn this learner into the permanent tutor.'],['Blank · Insufficient evidence','Absent, interrupted, inaccessible task, incomplete observation or no interpretable performance.','Arrange an equivalent opportunity. Do not assign zero or assume band 1.']])}
<p>The suggested band is the lowest of the four core criterion ratings. This is a conservative <em>local</em> rule: a strong layout should not conceal an inability to locate its controlling mask. It is not a statistical claim about ability. For example, <strong>3, 3, 2, 3</strong> gives a task score of <strong>11/16</strong> and suggested band <strong>2</strong>. The teacher may make a different documented judgment after reviewing the evidence. Keep the missing evidence blank rather than inventing a total.</p>
<p>A band needs the artifact, a specific observed action, an individual explanation and teacher verification. Access supports—larger text, extra processing time, assistive input, a written or recorded explanation, or an approved language support—do not reduce the band. Log task-solving hints and live co-production separately. Those conditions limit this scored attempt to 1 or 2; collect another independent performance before claiming 3 or 4.</p>
<h3>Do not turn preferences into fixed learning styles</h3><p>Offer demonstrations, clear text, examples and hands-on practice to everyone as the content requires. Ask which supports helped and test whether they improved access or performance. The evidence review by Pashler and colleagues did not establish a basis for assigning students fixed learning-style categories and matching instruction to them. A preference is useful feedback, not a diagnostic identity. <a href="https://journals.sagepub.com/doi/pdf/10.1111/j.1539-6053.2009.01038.x">Learning Styles: Concepts and Evidence</a>.</p>
<h2>A manageable assessment cycle</h2>{table(['When','Teacher action','Evidence'],[['Before the task','Ask about prior Photoshop exposure and access needs. Explain the rubric and allow a common induction.','Context note only; prior exposure and speed are not points.'],['Initial individual attempt','Use PS-A after prerequisite teaching. Observe a rotating sample of 4–6 learners; inspect everyone’s artifacts later.','Four criterion ratings only when the required evidence exists. Others remain incomplete.'],['Next lessons','Finish the observation/conversation rotation while peers do structured practice.','Specific actions and explanations, not a generic “worked well” note.'],['Practice and repair','Give one next step per learner. Use short partner coaching with role changes.','Feedback and revision record; distinguish guided practice from independent evidence.'],['2–3 weeks later','Use PS-B or DS-B with matched demands and comparable conditions.','A new attempt. Retain the original score and the actual support used.'],['After the retest','Review the criterion changes and choose the next action.','Two independent dates strengthen the profile, but do not certify a permanent ability.'],['At a new unit or after 42 days','Recheck the relevant skill. Honour an earlier teacher-set review date.','An old Photoshop band does not place students for sound editing, machinery or DS reasoning.']])}
<p>A whole class of 30 cannot all receive a defensible live conference in ten minutes. The plan deliberately spreads verification across lessons. A product score can be recorded first; the readiness band stays blank until the live action and explanation are captured. If fatigue, access, absence or unfamiliar vocabulary affected the attempt, record the condition and arrange another sample.</p>
<h2>A five-class pilot</h2>{table(['Class','70-minute sequence','Teacher focus'],[['1','5 context and access; 12 model; 10 guided practice; 25 individual PS-A; 10 peer response and file checks; 8 submission/next step.','Record conditions during the scored segment. Sample 4–6 live actions.'],['2','5 retrieval; 10 model a common fault; 35 individual repair or extension; 12 rotating conferences; 8 reflection.','Complete more baseline observations. Keep unobserved criteria blank.'],['3','5 think/write; 10 teacher demonstration of coaching; 30 alternating operator/coach turns; 15 independent retry; 10 debrief.','Observe balanced turns and coaching separately from technical achievement.'],['4','8 delayed recall; 12 targeted mini-lesson; 30 production application; 12 audience test/revision; 8 documentation.','Use each learner’s next step. Check whether the support helped.'],['5','5 retrieval; 15 changed brief; 25 independent work; 15 rolling conferences; 10 evidence and planning.','Make provisional seating changes if justified. Schedule PS-B 2–3 weeks after baseline.']])}
<h2>How a mixed team works</h2><p>For a team with four different readiness profiles, arrange the strongest and most supported learners diagonally. Review the actual room, access requirements and relationships before using the draft. The app distributes available bands, balances team sizes and lets you swap any two students. It does not infer needs from demographics or diagnose behaviour. A trio uses rotating operator, coach and checker roles; a fifth learner must have a meaningful rotating role and an independent turn.</p><ol><li>Everyone predicts the next action or drafts an answer independently.</li><li>Partners take equal turns explaining. The listener asks one useful question.</li><li>For software practice, the operator controls their own file. The coach prompts without taking the mouse or writing the answer. Swap roles after the short turn.</li><li>Partners compare results against a visible criterion, then each learner performs a small independent action.</li><li>Collect one team reflection on participation and one individual learning next step.</li></ol><p>These are original studio routines informed by the principles. They are not a claim to reproduce a licensed Kagan training programme. Use your Kagan training/materials for the exact named structures when required.</p>
<h3>Observe cooperation separately</h3><p>The four shared habits are balanced participation, coaching without taking over, using feedback, and planning a small next step. Record a behaviour and context: “Asked the partner to identify the mask thumbnail, waited, then swapped roles” is more useful than “good team member.” Quiet speech, disability, personality and popularity are not negative scores. Tool safety always needs its own named, teacher-observed clearance; a Photoshop band of 4 does not authorise a laser cutter.</p>
<h2>What to borrow from the friend’s Sheets</h2><p>The individual trackers separate skill references from a running log containing date, task, action, evidence and self-rating. The teacher trackers organise production checkpoints by phase and connect columns to gradebook assignments. Keep those useful structures. Replace the unrelated game/film standards with this course’s skills; keep completion, self-rating and achievement as distinct records.</p>{table(['Reference inspected','Adopt','Adapt'],[['Game Design teacher PTS: Instructions and S10 headers','Production phases, checkpoint links and assignment references.','Only a minimal task board may be projected. Private achievement and readiness stay in teacher records.'],['Film skill tracker: Skill Reference and Skill Log','A dated description of meaningful skill use with an artifact link.','Use MM12 and COM11 success evidence and curriculum codes.'],['Game Design skill tracker: Instructions and Skill Reference','Learner reflection and a recurring log rather than an end-of-project checkbox.','Do not call band 4 “professional level” based on one school task or average self-ratings into grades.'],['Film teacher PTS: Instructions','Enter a roster once and reuse it.','Use neutral student seating views and a separate teacher workbook.']])}<p>The friend’s Kaizen/Deming references concern an improvement cycle: make a plan, try it, study the evidence and adjust. That fits the reassessment loop. <strong>Kagan</strong> is the cooperative-learning source in your links. These are complementary ideas with different purposes.</p>
<h2>Student OS and the evidence map</h2><p>The teacher profile holds a learner goal, useful supports, next action, observed skill uses and diagnostic history. The separate downloadable Student Skill Passport lets a learner document a skill claim without exposing the teacher’s roster. The teacher verifies claims against the work before assigning a level. The teacher app is a local, single-user workspace; it is not a multi-user student portal with accounts or cross-device synchronisation.</p><p>Use one meaningful log entry when the learner makes a decision, solves a problem or revises from evidence. Do not require a form for every click. Start with two entries a week plus one project reflection. A typical record is: task ID, skill ID, actual date, what changed, evidence location, help used, self-rating, and next step. Teacher evidence additionally includes the method, observed criterion, verification and judgment. Preserve the baseline and revised artifacts.</p><p>The supplied <em>How Teens Win</em> supports a learner-owned small-goal conversation; the contents and selected passages from chapters 2 and 12–14 were inspected. Use a feasible next action and a check date, without turning motivation or personal goals into achievement marks. In <em>Show Your Work</em>, the inspected sections on revision tracking, non-writing assessments and individual oral exams support collecting visible process and explanation. Neither book validates a rank or an AI-detection score.</p>
<h2>Course and source reconciliation</h2>{changes}<p>The original assessment-guide copies were exact duplicates. Their distinction between guided practice and independent evidence is retained. The day-by-day Markdown and Excel rows were cross-referenced by lesson ID. Book audits and older architecture prompts are preserved as source notes, with their original claims about what was inspected retained as historical claims—not treated as new inspection in this run. The unprovided publisher books and unavailable tutorial footage were not silently inferred.</p>
<h3>What is complete and what still needs rehearsal</h3><p>The local app, Excel working workbook, original-workbook access, rubric, comparable task briefs, original geometric source artwork, source register and reusable production prompts are assembled. The Photoshop task deliberately measures foundational edit control and communication with a simple standardised asset. It does not claim to measure complex photo extraction, photography, all of Multimedia, or overall academic ability.</p><div class="note"><strong>Photoshop rehearsal:</strong> the installed build reports 27.10.0. The app launched, but computer-use control failed before a test document could be opened. The layer-mask procedure was checked against Adobe’s current documentation; the complete classroom procedure and genuine instructional screenshots remain unverified. A teacher-led pilot may use a live demonstration. Do not issue this as a fully rehearsed, self-guided novice tutorial yet.</div>
<p>The wider Citrus and sneaker teaching sequences still identify missing photographs and genuine screen captures. Their planning detail is available, but this release does not claim that every lesson in a 332-day plan is student-ready. The fabrication prompts name the actual missing deliverables and acceptance checks.</p>
<h2>Evaluation before wider use</h2><p>Pilot with a small set of anonymised work samples. Independently score the same 6–8 files with a colleague and discuss differences of more than one band. Tighten an ambiguous anchor before relying on the number for grouping. Compare performance under equivalent conditions, not just total-score movement. Track whether roles were balanced, whether the target skill improved, and whether any learner was repeatedly stuck coaching or waiting. Treat the band as provisional until that local calibration is convincing.</p><p>Do not interpret a movement from 1 to 2 as a measured amount of intelligence gained. It indicates a different observed performance against the local anchors. If the task, support or version changes substantially, show the two profiles and explain why a direct numerical comparison is limited.</p>
<h2>Sources</h2><ul>{research}</ul><p class="small">Google reference structures were read after access was granted. No reference workbook was edited, and no student roster was copied. See the Sources sheet for exact ranges. Research checked 13 September 2026.</p>'''
doc('Teacher_Guide.html','Kagan-informed readiness and a student skills system','A practical teacher guide to the diagnostic, the 1–4 profile, cooperative routines, reassessment and the consolidated resources.',guide)

rub=table(['Criterion','1 · Beginning','2 · Developing','3 · Independent','4 · Transfer'],[[r['name'],*r['bands']] for r in D['diagnosticRubrics']['PS']])
ps=f'''<div class="buttons"><a class="button" href="assets/badge-A.png" download>Download source A</a><a class="button" href="assets/badge-B.png" download>Download source B</a><a class="button" href="Photoshop_Workbook.html">Open printable workbook</a><a class="button" href="Teacher_Guide.html">Teacher guide</a></div>
<div class="note"><strong>Teacher-led pilot.</strong> Use this after the common model and guided practice. The written control paths are checked against Adobe documentation. The full workflow and real instructional captures still need rehearsal in the classroom Photoshop build. The finished design below is an original layout illustration, not a Photoshop screenshot.</div>
<div class="grid"><div><h2>Your job</h2><p>Design a small advertisement that invites students to a school making session. You will build an editable Photoshop file, make a deliberate layout choice, repair a fault and explain one decision. This is a starting-point check so your teacher can plan useful practice.</p><p>You may ask for help. Your teacher will record the help used during the individual attempt. Approved access supports remain available. Speed, confidence and prior Photoshop experience are not separate points.</p><h3>What to hand in</h3><ul><li>Your layered PSD before and after revision.</li><li>A PNG viewing copy at 1200 × 1500 pixels.</li><li>A short record of your decision, help and next step.</li><li>A live action or equivalent recorded demonstration arranged with the teacher.</li></ul></div><figure><img src="assets/composition-example.png" alt="Example portrait layout with Maker Night headline, a green circular lightning badge, event details and a call to action"><figcaption>Original layout illustration. Your composition may differ; meet the brief and keep it editable.</figcaption></figure></div>
<h2>Common induction before scoring</h2><p>The teacher models a small composition in short chunks. Watch the action, try it with support, then move to the individual brief. Practice files are not treated as independent evidence.</p>{table(['Action to model','Expected result','Common fault and repair'],[['File &gt; New; set width 1200 px, height 1500 px, RGB, 8 bit. Save as a PSD.','A portrait working file with a named editable master.','Check the unit is pixels rather than inches. Save in an accessible class folder.'],['File &gt; Place Embedded; select badge-A.png; commit the placement. Rename the placed layer Badge.','The source artwork is on its own layer.','If the wrong layer is active, select the Badge layer in the Layers panel before editing.'],['Select the circular badge with the Elliptical Marquee tool. Add a mask with Layer &gt; Layer Mask &gt; Reveal Selection.','The outer grey square is hidden; the circle remains.','If the outside remains and the circle disappears, undo and check which area was selected. An approximate edge is acceptable during induction.'],['Select the mask thumbnail. Use Brush (B): black hides, white reveals. Demonstrate one small hide/restore action.','The artwork remains intact while visibility changes.','If colour appears on the artwork, undo, then click the mask thumbnail. Do not flatten the file.'],['Use Type (T) for a headline and supporting event details. Use Edit &gt; Free Transform (Ctrl/Cmd+T) for composition.','Text remains editable and the reader can find the message.','Check which layer is active. Commit an edit before selecting another tool.'],['Save the PSD. Export a PNG using File &gt; Export &gt; Export As, then reopen the output.','Both an editable source and a viewing copy exist.','An exported PNG is not the editable master. Check actual output dimensions.']])}
<p class="small">Source: <a href="https://helpx.adobe.com/photoshop/desktop/create-masks/layer-masks/add-layer-masks.html">Adobe’s current layer-mask guidance</a>. The circle is a deliberately simple diagnostic stimulus. This task does not assess advanced photographic selection.</p>
<h2>PS-A · Maker Night</h2><div class="card"><p><strong>Audience:</strong> students who have not tried the making studio. <strong>Message:</strong> everyone can bring an idea and make a first version.</p><p>Use source A and these exact information items: <strong>MAKER NIGHT</strong>; <strong>Friday · 3:30 · Studio</strong>; <strong>Ask your teacher</strong>. Keep the text editable. You choose the layout, sizes, background colour and spacing.</p><ol><li>Create the specified portrait file and place the badge on its own layer.</li><li>Mask the grey background so the badge sits cleanly on your chosen background. Keep the source reversible.</li><li>Create a clear reading order for the event, supporting details and action. Do not put essential small text over a busy edge.</li><li>Save <code>PS-A_ID_v1.psd</code>. Ask a partner what they notice first; record their answer before explaining your intention.</li><li>Make one useful revision. Save <code>PS-A_ID_v2.psd</code> and export <code>PS-A_ID.png</code>.</li><li>During the teacher check, show the mask, restore a small area without destroying the source, then repair it. Explain why the correct thumbnail matters.</li></ol></div>
<h3>Changed-condition check</h3><p>Give every learner both short checks, across the live observation and revision: “Your headline competes with the badge; make the event the first read,” and “A small part of the badge has disappeared; locate and repair the responsible mask area.” Predict the effect before editing. Then perform the edit and explain whether the result matched the prediction. Everyone gets a transfer opportunity; an extra format is not required to earn band 4.</p>
<h2>PS-B · Repair Café</h2><div class="card"><p>Use this 2–3 weeks later after targeted teaching. Use source B, the same 1200 × 1500 pixel format, the same four criteria, comparable working time and equivalent access supports.</p><p><strong>Audience:</strong> students curious about repairing rather than replacing items. <strong>Message:</strong> bring a small repair idea and ask for help.</p><p>Required text: <strong>REPAIR CAFÉ</strong>; <strong>Thursday · 3:30 · Studio</strong>; <strong>Ask your teacher</strong>. Compose from the supplied source, preserve editable text and a reversible mask, test the reading order, save v1/v2, and explain an independent repair. The changed-condition check uses the same type of mask or hierarchy fault as PS-A, in a different position.</p><p>Save <code>PS-B_ID_v1.psd</code>, <code>PS-B_ID_v2.psd</code> and <code>PS-B_ID.png</code>. Use the same help log. The new topic and mirrored geometric asset provide a changed task; equivalence should be checked through local moderation.</p></div>
<h2>Timing and teacher evidence</h2>{table(['Minutes','Activity'],[['0–5','Context, access and prior experience note.'],['5–17','Common teacher model.'],['17–27','Guided practice; resolve setup barriers.'],['27–52','Individual task. Record any instructional help during this segment. Teacher samples 4–6 learners.'],['52–62','Reader response, revision and output check. Preserve the earlier version.'],['62–70','Submit, record next action and arrange remaining live checks.']])}<p>The individual attempt can continue in the next class when required. Do not give a learner a lower level because the teacher did not reach them. Record incomplete evidence and finish the rotation during subsequent production work.</p>
<h2>Assessment anchors</h2>{rub}<p><strong>Task score:</strong> sum four observed ratings; possible range 4–16. <strong>Suggested readiness:</strong> lowest core criterion, with a cap of 2 when instructional hints or modelling were needed during the scored attempt. The teacher records the band, rationale and next check. Keep access supports distinct from task-solving help. Missing evidence stays blank.</p>
<h2>Useful supports and extensions</h2><p>Provide a printed sequence, larger UI, extra processing time, prepared source download, an assistive input device or a written/recorded explanation when appropriate. Log the support. A reduced layer count is acceptable if the same mask, hierarchy, repair and explanation evidence can still be demonstrated. If an outcome changes, record a different task rather than treating the score as directly comparable.</p><p>After the core is secure, invite a square-format adaptation or an alternative audience message. Keep the required criteria stable: more decorative effects do not automatically produce a stronger band. Pair coaching is practice; the final change and explanation belong to the individual.</p>'''
doc('Photoshop_Diagnostic.html','Photoshop readiness diagnostic','Build, repair and explain an editable school-event advertisement. PS-A establishes the baseline; PS-B provides a comparable later attempt.',ps)
workbook='''<div class="buttons"><a class="button" href="Photoshop_Diagnostic.html">Read the task</a><button onclick="window.print()">Print or save PDF</button></div><p>Name or school ID: ____________________ &nbsp; Course: __________ &nbsp; Date: __________ &nbsp; Task: PS-A / PS-B</p><h2>Before I build</h2><p>What should the audience notice first, and what should they do next? Sketch two possible layouts. Choose one and explain why.</p><div class="answer"></div><div class="answer"></div><h2>My file and support record</h2>'''+table(['Record','My response'],[['Editable source filename','________________________________________'],['Source asset and permission','________________________________________'],['Access support used','________________________________________'],['Instructional hints during my own attempt','________________________________________'],['PNG dimensions checked','________________________________________']])+'''<h2>Before I change it</h2><p>What did the reader notice? What specific problem or mismatch will I address?</p><div class="answer"></div><p>Predict: if I change ____________________, I expect ____________________ because ____________________.</p><div class="answer"></div><h2>After the revision</h2><p>Point to the layer or mask that controls the change. What happened, and what evidence shows whether it helped?</p><div class="answer"></div><h2>My next step</h2><p>One skill I used: ____________________ &nbsp; Self-rating for reflection: 1 / 2 / 3 / 4 / unsure</p><p>Evidence location: ___________________________________________________</p><p>One action I will practise before the next check:</p><div class="answer"></div><p class="small">Your self-rating is a claim for discussion. Your teacher uses the observed evidence to make a separate judgment. A support or access need is not a fixed learning-style label.</p>'''
doc('Photoshop_Workbook.html','Photoshop decision and evidence workbook','Printable student record for PS-A and PS-B. Keep the first and revised versions.',workbook)

dsrub=table(['Criterion','1','2','3','4'],[[r['name'],*r['bands']] for r in D['diagnosticRubrics']['DS']])
ds='''<div class="buttons"><a class="button" href="Teacher_Guide.html">Teacher guide</a><button onclick="window.print()">Print or save PDF</button></div><div class="note"><strong>Local reasoning diagnostic.</strong> This synthetic classroom case is not a real deployment, an official IB paper or an IA assessment. Use the four local criteria for a starting profile, not an IB 1–7 prediction.</div><h2>DS-A · Library entry</h2><p>A fictional college is testing a card-based library entry system. The system reads a card ID, retrieves its stored similarity score from a classroom test file, and accepts entry when <strong>score ≥ threshold</strong>. The score is a made-up diagnostic value, not the probability that a person has a valid card. Staff can manually check rejected visitors.</p><p>The table’s known status was assigned by the test designer. This tiny balanced sample does not estimate real-world accuracy or represent a population.</p>'''+table(['Test ID','Known status','Score'],[['A1','Valid card',0.91],['A2','Valid card',0.78],['A3','Valid card',0.64],['A4','Invalid card',0.83],['A5','Invalid card',0.67],['A6','Invalid card',0.30]])+'''<div class="grid"><div class="card"><h3>Source A · Developer note</h3><p>Fictional internal pilot note, 10 September 2026: “The threshold can be changed. Higher thresholds reject more attempts. Our six-case test is a starting diagnostic and does not show performance for the whole campus.”</p><p class="small">Author: development team. Purpose: explain the prototype. Evidence: the supplied small test. Interest: demonstrating a workable system.</p></div><div class="card"><h3>Source B · Access committee note</h3><p>Fictional meeting note, 11 September 2026: “Rejected legitimate users may wait for staff. The pilot should record queue time and manual-check outcomes before any wider rollout.”</p><p class="small">Author: access committee. Purpose: examine access costs. Evidence: anticipated risks, with no measured queue data yet.</p></div></div><h2>Your individual response</h2><ol><li>Trace the input, processing, output and human decision at a threshold of 0.75. Identify which valid and invalid cards are accepted or rejected.</li><li>Compare the consequences at thresholds 0.60 and 0.85. Explain one cost to a legitimate user and one concern for library staff.</li><li>Use both sources. Identify one useful contribution and one limitation of each. Do not describe the synthetic notes as independent research findings.</li><li>Recommend a provisional threshold or a pilot condition. Support the judgment, identify a trade-off, and name the evidence that would change your recommendation.</li></ol><p>Answer in clear prose, an annotated diagram, or an agreed oral/recorded explanation that preserves the same reasoning demand.</p><div class="answer"></div><div class="answer"></div><h2>Teacher follow-up</h2><p>“Suppose the score of A3 changes from 0.64 to 0.76. What changes at threshold 0.75, and what does not change?” The learner should identify that one valid card moves from rejected to accepted; the rule, other cases and missing real-world evidence remain unchanged.</p><h2>DS-B · Equipment checkout</h2><p>Use after targeted practice. A fictional equipment-loan desk uses the same kind of scored classroom rule to approve a checkout. A staff member can review rejected requests. Use the same question structure, timings and rubric, but use this table and threshold 0.70. Compare 0.55 and 0.80.</p>'''+table(['Test ID','Known status','Score'],[['B1','Eligible request',0.88],['B2','Eligible request',0.73],['B3','Eligible request',0.59],['B4','Ineligible request',0.78],['B5','Ineligible request',0.62],['B6','Ineligible request',0.25]])+'''<p><strong>Source A:</strong> a fictional checkout developer says the six-case sample demonstrates how the adjustable rule works, not population performance. <strong>Source B:</strong> a fictional student equipment committee asks the pilot to measure waiting time, missed access and manual-review outcomes. Each source has the same role and evidential limitation as in DS-A. Follow-up: change B3 to 0.71 and ask what changes at 0.70.</p><h2>Scoring and timing</h2><p>5 minutes to establish access; 10 to model an unrelated simple rule; 10 guided tracing; 25 individual response; 12 minutes of rolling teacher follow-ups; 8 minutes to record the next action. Finish the observation rotation in subsequent lessons. Prior subject knowledge and reading speed are context, not bonus points.</p>'''+dsrub+'''<p>Use the same missing-evidence, support and teacher-verification rules as the Photoshop diagnostic. The four local ratings total 4–16 when complete. They do not convert to an official IB grade.</p><details><summary>Teacher-only reasoning key</summary><p>DS-A at 0.75: valid accepted A1/A2; valid rejected A3; invalid accepted A4; invalid rejected A5/A6. At 0.60: all valid accepted, A4/A5 incorrectly accepted. At 0.85: only A1 accepted, no invalid accepted; A2/A3 rejected. DS-B at 0.70: B1/B2 accepted, B3 rejected, B4 incorrectly accepted, B5/B6 rejected. At 0.55: all eligible accepted and B4/B5 incorrectly accepted. At 0.80: only B1 accepted and no ineligible requests accepted. There is no uniquely justified policy threshold without a cost criterion and more evidence. Credit a supported conditional judgment; do not reward the largest number automatically.</p></details>'''
key_start=ds.index('<details><summary>Teacher-only reasoning key</summary>')
key=ds[key_start:].replace('<details><summary>Teacher-only reasoning key</summary>','<h2>Reasoning key</h2>').replace('</details>','')
ds=ds[:key_start]
answer='The learner should identify that one valid card moves from rejected to accepted; the rule, other cases and missing real-world evidence remain unchanged.'
ds=ds.replace(' '+answer,'')
doc('Digital_Society_Teacher_Key.html','Digital Society diagnostic: teacher reference','Keep this file with teacher materials. Share the separate task with learners.',key+'<h2>Changed-condition response</h2><p>'+answer+'</p><p>Observe the individual explanation and record the task version and instructional help. Finish missing checks later; do not infer a band from unobserved work.</p>')
doc('Digital_Society_Diagnostic.html','Digital Society readiness diagnostic','Trace a simple decision rule, examine source limits, compare stakeholder consequences and defend a conditional judgment.',ds)
print('Created teacher guide, Photoshop task/workbook and DS task')
